shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-elevated: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-dark: #c5beb0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #284058;
    --gold: #d49b4b;
    --font-serif-en: 'Playfair Display', Georgia, serif;
    --font-body-en: 'Lora', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Strict Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    color: var(--body);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-body-en);
    line-height: 1.78;
  }

  /* Sticky Masthead & Progress Bar */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.75rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .wsj-monogram {
    font-family: var(--font-serif-en);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-decoration: none;
  }

  .brand-divider {
    width: 1px;
    height: 14px;
    background: var(--line-dark);
  }

  .desk-tag {
    font-family: var(--font-sans);
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-radius: 999px;
    padding: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.28rem 0.75rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  .progress-track {
    height: 2px;
    width: 100%;
    background: transparent;
  }

  .progress-bar {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s linear;
  }

  /* Hero Header */
  .hero {
    max-width: 1120px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--ink);
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    margin-bottom: 1.25rem;
  }

  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 24px;
    height: 2px;
    background: var(--accent);
  }

  .article-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.24;
    color: var(--ink);
    letter-spacing: -0.01em;
    margin-bottom: 1.5rem;
    max-width: 960px;
  }

  :host([lang="en"]) .article-title {
    font-family: var(--font-serif-en);
    font-weight: 800;
    line-height: 1.12;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-name {
    color: var(--ink);
    font-weight: 600;
  }

  /* Executive Metric Strip */
  .telemetry-strip {
    max-width: 1120px;
    margin: 0 auto;
    padding: 1.75rem 1.5rem;
    border-bottom: 1px solid var(--line);
    background: linear-gradient(180deg, rgba(243, 239, 230, 0.55) 0%, rgba(250, 248, 244, 0) 100%);
  }

  .telemetry-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1.5rem;
  }

  .telemetry-item {
    border-left: 2px solid var(--accent);
    padding-left: 1rem;
  }

  .telemetry-num {
    font-family: var(--font-mono);
    font-size: 1.65rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.15;
    margin-bottom: 0.25rem;
  }

  .telemetry-lbl {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Main Editorial Grid */
  .editorial-container {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.75rem 1.5rem 4rem;
  }

  .section-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 340px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  .prose-col {
    min-width: 0;
  }

  .rail-col {
    min-width: 0;
    position: sticky;
    top: 5rem;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Styling (No drop-caps or text-wrap:pretty on Chinese!) */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.5rem;
    letter-spacing: 0.01em;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    letter-spacing: 0;
  }

  .prose-p.lead-p {
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.75rem;
    line-height: 1.75;
  }

  .prose-p.question-callout {
    font-family: var(--font-serif-cn);
    font-size: 1.22rem;
    font-style: italic;
    color: var(--accent);
    background: var(--paper-card);
    padding: 1rem 1.35rem;
    border-radius: 4px;
    border-left: 3px solid var(--ink);
    margin: 1.5rem 0;
  }

  :host([lang="en"]) .prose-p.question-callout {
    font-family: var(--font-body-en);
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.16) 0%, rgba(184, 93, 25, 0.24) 100%);
    color: var(--ink);
    padding: 0.08em 0.28em;
    border-radius: 2px;
    font-weight: 600;
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
  }

  /* Chapter Divider */
  .chapter-divider {
    margin: 3rem 0 2rem;
    padding-top: 1.75rem;
    border-top: 1px solid var(--line-dark);
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.1em;
  }

  .chapter-title {
    font-family: var(--font-sans);
    font-size: 0.95rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--ink);
  }

  /* Sidebar Callout Cards (Pull Quotes & Metrics) */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--ink);
    border-bottom: 1px solid var(--line-dark);
    padding: 1.5rem 1.35rem;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.12rem;
    font-weight: 600;
    line-height: 1.6;
    color: var(--ink);
    margin-bottom: 0.85rem;
  }

  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--font-serif-en);
    font-size: 1.15rem;
    line-height: 1.45;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-sans);
    font-size: 0.76rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--accent);
  }

  .metric-card {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.6rem 1.4rem;
    border-radius: 4px;
    border-left: 4px solid var(--gold);
    box-shadow: 0 8px 24px rgba(15, 29, 43, 0.08);
  }

  .metric-card .metric-val {
    font-family: var(--font-mono);
    font-size: 2.5rem;
    font-weight: 700;
    color: var(--gold);
    line-height: 1.05;
    margin-bottom: 0.5rem;
  }

  .metric-card .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.85rem;
    font-weight: 600;
    color: #ffffff;
    margin-bottom: 0.4rem;
    line-height: 1.4;
  }

  .metric-card .metric-note {
    font-family: var(--font-sans);
    font-size: 0.74rem;
    color: #b0c0d0;
    line-height: 1.45;
  }

  /* Bespoke Editorial Dossier Box */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    padding: 1.35rem;
    border-radius: 4px;
  }

  .dossier-head {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    padding-bottom: 0.65rem;
    margin-bottom: 0.85rem;
    border-bottom: 1px solid var(--line-dark);
  }

  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }

  .dossier-list li {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    line-height: 1.5;
    color: var(--body);
    display: flex;
    justify-content: space-between;
    gap: 0.75rem;
    border-bottom: 1px dashed var(--line);
    padding-bottom: 0.5rem;
  }

  .dossier-list li:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .dossier-key {
    color: var(--muted);
    font-weight: 500;
  }

  .dossier-val {
    font-family: var(--font-mono);
    font-weight: 600;
    color: var(--ink);
    text-align: right;
  }

  /* Full-Bleed Visual Feature: China Social Commerce Funnel & Shanghai Studios */
  .visual-breakout {
    margin: 3rem 0;
    background: var(--navy-bg);
    color: var(--paper);
    border-radius: 6px;
    padding: 2.25rem 2rem;
    border: 1px solid var(--navy-line);
  }

  .visual-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--navy-line);
  }

  .visual-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--gold);
    margin-bottom: 0.35rem;
  }

  .visual-title {
    font-family: var(--font-sans);
    font-size: 1.25rem;
    font-weight: 700;
    color: #ffffff;
  }

  .visual-sub {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: #a8b9ca;
  }

  .svg-container {
    width: 100%;
    overflow: hidden;
  }

  .svg-container svg {
    display: block;
    width: 100%;
    height: auto;
  }

  /* Photo Caption Frame for p22 */
  .studio-caption-frame {
    margin-top: 2.5rem;
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-radius: 6px;
    overflow: hidden;
  }

  .studio-diagram-wrap {
    background: #192736;
    padding: 1.5rem;
    border-bottom: 1px solid var(--line-dark);
  }

  .photo-caption-text {
    padding: 1.1rem 1.4rem;
    font-family: var(--font-sans);
    font-size: 0.86rem;
    color: var(--muted);
    line-height: 1.55;
    margin-bottom: 0;
    display: flex;
    align-items: center;
    gap: 0.65rem;
  }

  .photo-caption-text::before {
    content: "STUDIO LOG";
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    background: var(--ink);
    color: var(--paper);
    padding: 0.18rem 0.5rem;
    border-radius: 2px;
    flex-shrink: 0;
  }

  /* Footer */
  .ed-footer {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
    border-top: 2px solid var(--ink);
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
    font-family: var(--font-sans);
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Responsive Reflow */
  @media (max-width: 920px) {
    .telemetry-grid {
      grid-template-columns: repeat(2, 1fr);
    }
    .section-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .rail-col {
      position: static;
      order: 2;
    }
  }

  @media (max-width: 540px) {
    .hero {
      padding: 2.25rem 1.15rem 1.75rem;
    }
    .telemetry-strip,
    .editorial-container,
    .ed-footer {
      padding-left: 1.15rem;
      padding-right: 1.15rem;
    }
    .telemetry-grid {
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
    }
    .telemetry-num {
      font-size: 1.35rem;
    }
    .visual-breakout {
      padding: 1.35rem 1rem;
    }
    .prose-p {
      font-size: 1.05rem;
    }
    .prose-p.lead-p {
      font-size: 1.12rem;
    }
  }
